const CHANNEL_HANDLE = 'yourhandle'; // <-- set this to your own Instagram @handle
const CHANNEL_ACCENT = '#C6FF3D'; 

const items = $input.all();
let aiData = {};
try {
  let rawText = items[0].json.content?.parts?.[0]?.text || items[0].json.output;
  const clean = rawText.replace(/```json/g,'').replace(/```/g,'').trim();
  aiData = JSON.parse(clean.substring(clean.indexOf('{'), clean.lastIndexOf('}') + 1));
} catch(e) { throw new Error("Failed to parse AI output: " + e.message); }

const cleanerItems = $('Extract Content from Articles').all();
const slides = aiData.slides || [];
const totalSlides = slides.length + 2; // Hook + Stories + Endcard

// --- RANDOMIZED GTA IMAGES (For Slide 1 and Endcard) ---
const gtaImages = [
  'https://i.postimg.cc/2S46y4zN/gta6-jason-and-lucia-1-poster-en.jpg',
  'https://i.postimg.cc/sxqYjp39/gta6-boobie-ike-portrait.jpg',
  'https://i.postimg.cc/T24qJXnw/gta6-brian-heder-portrait.jpg',
  'https://i.postimg.cc/QNykJrcM/gta6-cal-hampton-portrait.jpg',
  'https://i.postimg.cc/J72c5WjD/gta6-drequan-priest-portrait.jpg',
  'https://i.postimg.cc/jdn68khP/gta6-jason-and-lucia-2-portrait.jpg',
  'https://i.postimg.cc/QdLQvk6Y/gta6-raul-bautista-portrait.jpg',
  'https://i.postimg.cc/XYMftc2z/gta6-real-dimez-portrait.jpg',
  'https://i.postimg.cc/654VH1hV/gta6-trailer1-announcement-phone.jpg'
];

const shuffledImages = [...gtaImages].sort(() => 0.5 - Math.random());
const hookImg = shuffledImages[0];
const endImg = shuffledImages[1];
const FALLBACK_GTA_IMG = shuffledImages[2];

const usedImages = new Set();

function pickUniqueImage(sourceIndex) {
  const story = cleanerItems[sourceIndex]?.json || {};
  const ownCandidates = [story.scraped_image, ...(story.images || [])].filter(Boolean);

  for (const url of ownCandidates) {
    if (!usedImages.has(url)) { usedImages.add(url); return url; }
  }
  for (const item of cleanerItems) {
    const candidates = [item.json.scraped_image, ...(item.json.images || [])].filter(Boolean);
    for (const url of candidates) {
      if (!usedImages.has(url)) { usedImages.add(url); return url; }
    }
  }
  return FALLBACK_GTA_IMG; 
}

const vibrantColors = ['#00FFCC', '#FF00FF', '#FFFF00', '#FF3366', '#33CCFF', '#C6FF3D', '#FF9900'];

function applyHighlights(text, highlights) {
  let out = text;
  (highlights || []).forEach(phrase => {
    if (!phrase) return;
    const esc = phrase.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const randomColor = vibrantColors[Math.floor(Math.random() * vibrantColors.length)];
    out = out.replace(new RegExp(`(${esc})`, 'gi'), `<span class="accent-text" style="color:${randomColor};">$1</span>`);
  });
  return out;
}

function autoFitScript(targetId, maxHeightFraction, startSize, minSize) {
  return `<script>
  (function(){
    var el = document.getElementById('${targetId}');
    if(!el) return;
    var maxH = 1350 * ${maxHeightFraction};
    var size = ${startSize};
    el.style.fontSize = size + 'px';
    while (el.scrollHeight < maxH && size < 400) { size += 4; el.style.fontSize = size + 'px'; }
    while (el.scrollHeight > maxH && size > ${minSize}) { size -= 3; el.style.fontSize = size + 'px'; }
  })();
  </script>`;
}

function storyHeadlineSize(text) {
  const len = (text || '').length;
  return len <= 20 ? 128 : len <= 35 ? 110 : len <= 50 ? 92 : 82;
}

const BASE = `
