  /* Pro Textures & Overlays */
  .grid-overlay { position:absolute; inset:0; background-image:repeating-linear-gradient(0deg, rgba(255,255,255,0.02) 0px, rgba(255,255,255,0.02) 1px, transparent 1px, transparent 30px); z-index:4; pointer-events:none; }
  .scrim { position:absolute; inset:0; background:linear-gradient(180deg, rgba(0,0,0,0) 30%, rgba(0,0,0,0.6) 55%, rgba(0,0,0,0.95) 75%, #+1234567890%); z-index:5; }

