  .badge span { font-family:'Anton', sans-serif; font-size:52px; color:#ffffff; }
  .badge-center { margin:0 auto 30px; }
  .badge-corner { position:absolute; top:48px; right:48px; z-index:10; }

  /* Slide Counter */
  .slide-counter { position:absolute; top:78px; left:56px; font-family:'Inter', sans-serif; font-weight:700; font-size:24px; color:rgba(255,255,255,0.4); letter-spacing: 2px; z-index:10; }

  .rule { width:110px; height:6px; background:rgba(255,255,255,0.9); margin:0 auto 32px; border-radius:3px; }
  .headline { font-family:'Anton', sans-serif; text-transform:uppercase; line-height:1.05; letter-spacing:0.5px; filter: drop-shadow(0 4px 10px rgba(0,0,0,0.5)); }
  .headline-white { color:#ffffff; }

