  .accent-text { font-weight:700; }

  .gradient-sunset {
    background: linear-gradient(90deg, #D4326E 0%, #F2903F 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    display: inline-block;
  }

  .cta-text { font-family:'Inter', sans-serif; font-weight:800; line-height:1.18; }
