`;

const results = [];

// SLIDE 1: HOOK 
const rawHookText = aiData.hook_headline || '';
const formattedHook = rawHookText.replace(/(Grand\s*Theft\s*Auto(?:\s*(?:6|VI))?|GTA(?:\s*(?:6|VI))?)/gi, '<span class="gradient-sunset">$1</span>');

const slide1 = `<!DOCTYPE html><html><head><style>${BASE}</style></head><body><div class="w">
  <img class="hero-img" src="${hookImg}"/>
  <div class="grid-overlay"></div>
  <div class="scrim"></div>
  <div class="content hook-content">
    <div class="badge badge-center"><span>G</span></div>
    <div class="rule"></div>
    <div id="hookHeadline" class="headline headline-white" style="font-size:140px;">${formattedHook}</div>
  </div>
</div>
${autoFitScript('hookHeadline', 0.40, 140, 56)}
</body></html>`;
results.push({ json:{slide_number:1,type:'hook'}, binary:{index_html: await this.helpers.prepareBinaryData(Buffer.from(slide1),'index.html','text/html')} });

// SLIDES 2-N: STORIES (Reverted back to full cover image)
for (let i=0;i<slides.length;i++){
  const s = slides[i];
  const img = pickUniqueImage(s.source_index);
  const caption = applyHighlights(s.caption, s.highlights);
  const headlineSize = storyHeadlineSize(s.headline);

  const currentNum = String(i + 2).padStart(2, '0');
  const totalNum = String(totalSlides).padStart(2, '0');

  const html = `<!DOCTYPE html><html><head><style>${BASE}</style></head><body><div class="w">
    <img class="hero-img" src="${img}"/>
    <div class="grid-overlay"></div>
    <div class="scrim"></div>
    <div class="slide-counter">${currentNum} / ${totalNum}</div>
    <div class="badge badge-corner"><span>G</span></div>
    <div class="content">
      <div class="headline headline-accent" style="font-size:${headlineSize}px;">${s.headline}</div>
      <div class="caption">${caption}</div>
    </div>
  </div></body></html>`;

  const link = cleanerItems[s.source_index]?.json?.link;
  results.push({ json:{slide_number:i+2,type:'story',source_link:link}, binary:{index_html: await this.helpers.prepareBinaryData(Buffer.from(html),'index.html','text/html')} });
}

// FINAL SLIDE: ENDCARD 
const endSlide = `<!DOCTYPE html><html><head><style>${BASE}</style></head><body><div class="w">
  <img class="hero-img" src="${endImg}"/>
  <div class="grid-overlay"></div>
  <div class="scrim"></div>
  <div class="badge badge-corner"><span>G</span></div>
  <div class="content">
    <div id="ctaText" class="cta-text" style="font-size:80px;">
      <span class="cta-white">For more </span><span class="gradient-sunset">GTA 6 news</span><br>
      <span class="cta-white">follow </span><span class="gradient-sunset">${CHANNEL_HANDLE}!</span>
    </div>
  </div>
</div>
${autoFitScript('ctaText', 0.15, 80, 46)}
</body></html>`;
results.push({
  json:{ slide_number: slides.length+2, type:'endcard', caption: aiData.caption, topic_slugs: aiData.topic_slugs,
         source_links: slides.map(s => cleanerItems[s.source_index]?.json?.link) },
  binary:{index_html: await this.helpers.prepareBinaryData(Buffer.from(endSlide),'index.html','text/html')}
});

return results;

const rssItems = $('Parse Article URLs').all();
const scrapedItems = $input.all();
const results = [];

const DEFAULT_BG = "https://images.unsplash.com/photo-1620712943543-bcc4688e7485?q=80&w=1080&auto=format&fit=crop";
const BAD_PATTERNS = /logo|icon|avatar|sprite|pixel|tracking|spacer|blank\.gif|\.gif|\.svg|data:image|flexiimages|scorecardresearch|doubleclick|googlesyndication/i;

for (let i = 0; i < scrapedItems.length; i++) {
  const html = scrapedItems[i].json.data || "";
  let bgImage = DEFAULT_BG;

  try {
    const match = html.match(/<meta property="og:image" content="([^"]+)"/);
    if (match && match[1]) bgImage = match[1];
  } catch (e) {}

  let images = [];
  try {
    const imgMatches = [...html.matchAll(/<img[^>]+(?:src|data-src)="([^"]+)"[^>]*>/gi)];
    const seen = new Set();
    for (const m of imgMatches) {
      let src = m[1];
      if (!src || BAD_PATTERNS.test(src)) continue;
      if (src.startsWith('//')) src = 'https:' + src;
      if (!src.startsWith('http')) continue;
      if (seen.has(src)) continue;
      seen.add(src);
      images.push(src);
      if (images.length >= 6) break;
    }
  } catch (e) {}

  if (bgImage !== DEFAULT_BG && !images.includes(bgImage)) images.unshift(bgImage);
  if (images.length === 0) images = [bgImage];

  let fullText = "";
  try {
    const pTags = html.match(/<p\b[^>]*>(.*?)<\/p>/gi);
    if (pTags && pTags.length > 0) {
      fullText = pTags.map(p => p.replace(/<[^>]+>/g, '')).join('\n\n');
    }
  } catch (e) {}

  if (fullText.length < 200 && rssItems[i]) {
    fullText = rssItems[i].json.contentSnippet || rssItems[i].json.content || "";
  }

  const cleanContent = fullText.substring(0, 30000);

  if (rssItems[i] && cleanContent.length > 100) {
    results.push({
      json: {
        title: rssItems[i].json.title,
        content: cleanContent,
        link: rssItems[i].json.link,
        scraped_image: bgImage,
        images: images
      }
    });
  }
}

// Remove images that repeat across multiple articles (site-wide boilerplate, not real story photos)
const freq = {};
results.forEach(r => r.json.images.forEach(img => { freq[img] = (freq[img] || 0) + 1; }));
results.forEach(r => {
  let filtered = r.json.images.filter(img => freq[img] === 1);
  if (filtered.length === 0) filtered = [r.json.scraped_image];
  r.json.images = filtered;
});

return results;

// 1. Fetch the 6 unique IDs directly from the Loop's Done Branch input
const items = $input.all();
const mediaIds = items.map(item => item.json.id).filter(id => id).slice(0, 10);

// 2. Extract the exact caption from the AI Analyst node
const aiItem = $('AI Content Analysis').first();
let aiCaption = "";

try {
  let rawText = aiItem.json.content.parts[0].text;
  const cleanText = rawText.replace(/```json/g, "").replace(/```/g, "").trim();
  const data = JSON.parse(cleanText);
  aiCaption = data.caption;
} catch (e) {
  aiCaption = "Which story is your favorite? Let us know in the comments. #GTA6";
}

// 3. Output the exact array and caption
return {
  json: {
    children: mediaIds,
    caption: aiCaption
  }
};

const html = $input.first().json.data;

const todayIdx = html.search(/Today\s*\d+\s*stories/i);
const yesterdayIdx = html.search(/Yesterday\s*\d+\s*stories/i);
const todayHtml = todayIdx !== -1
  ? html.slice(todayIdx, yesterdayIdx !== -1 ? yesterdayIdx : todayIdx + 40000)
  : html;

const anchorRegex = /<a[^>]+href="(https?:\/\/(?!gta6\.channel)[^"]+)"[^>]*>([\s\S]*?)<\/a>/g;
const results = [];
let match;

while ((match = anchorRegex.exec(todayHtml)) !== null) {
  const href = match[1];
  const inner = match[2];
  if (href.includes('news.google.com')) continue;
  if (href.includes('reddit.com')) continue;
  const text = inner.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
  if (!text || text.length < 15) continue;

  results.push({ json: { title: text, link: href } });
}

return results;
